// Knowledge base retrieval — port of help/helpbot/kb.py.
//
// The markdown lives pre-chunked in ./knowledge.js (generated by
// tools/build_knowledge.mjs with the exact Python chunking), so this
// module only builds the BM25 index at load and answers queries:
// search, coverage (off-topic guard), command index, guides, context.

import { FILES, CHUNKS } from './knowledge.js';

/** BM25 parameters (match kb.py). */
const K1 = 1.5;
const B = 0.75;

const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'can', 'do',
  'does', 'for', 'from', 'how', 'i', 'if', 'in', 'into', 'is', 'it',
  'its', 'me', 'my', 'not', 'of', 'on', 'or', 'our', 'so', 'the', 'them',
  'then', 'there', 'these', 'they', 'this', 'to', 'us', 'was', 'we',
  'what', 'when', 'where', 'which', 'who', 'why', 'will', 'with', 'you',
  'your', 'please', 'tell', 'about', 'bot', 'forge',
]);

const TOKEN_RE = /[a-z0-9]+/g;
const SLASH_RE = /(?<![\w/])\/([a-z][a-z0-9_]{1,30})\b/g;

/** Very light suffix stripping so query and document wording line up
 *  (port of kb.py _stem — conservative, never below 4 chars). */
function stem(token) {
  if (token.length > 5 && token.endsWith('ing')) token = token.slice(0, -3);
  else if (token.length > 4 && token.endsWith('ed')) token = token.slice(0, -2);
  if (token.length > 3 && token.endsWith('s') && !token.endsWith('ss')) {
    token = token.slice(0, -1);
  }
  return token;
}

/** Lowercase word tokens, stopwords removed, lightly stemmed. */
export function tokenize(text) {
  const out = [];
  for (const t of String(text || '').toLowerCase().match(TOKEN_RE) || []) {
    if (STOPWORDS.has(t)) continue;
    if (t.length > 1 || /\d/.test(t)) out.push(stem(t));
  }
  return out;
}

/** title getter (port of Chunk.title). */
function titleOf(chunk) {
  return chunk.heading ? chunk.heading.split(' > ').pop() : chunk.source;
}

// ── index (built once per invocation) ────────────────────────────────────

let IDX = null;

function load() {
  if (IDX) return IDX;
  const chunks = CHUNKS.map((c, id) => ({ id, ...c, terms: new Map(), length: 1 }));
  const byId = new Map();
  const commands = new Map(); // command name (no slash) -> Set(chunk ids)
  const df = new Map();
  const fileByStem = new Map();
  const byStem = new Map(); // stem -> FILES entry (guides lookup order)

  for (const f of FILES) {
    byStem.set(f.stem, f);
    fileByStem.set(f.stem, f);
  }

  for (const chunk of chunks) {
    byId.set(chunk.id, chunk);
    // Headings carry extra weight ×3 (matches kb.py).
    for (const term of tokenize(chunk.heading)) {
      chunk.terms.set(term, (chunk.terms.get(term) || 0) + 3);
    }
    for (const term of tokenize(chunk.text)) {
      chunk.terms.set(term, (chunk.terms.get(term) || 0) + 1);
    }
    chunk.length = Math.max([...chunk.terms.values()].reduce((a, b) => a + b, 0), 1);
    for (const term of new Set(chunk.terms.keys())) {
      df.set(term, (df.get(term) || 0) + 1);
    }
    for (const m of chunk.text.matchAll(SLASH_RE)) {
      if (!commands.has(m[1])) commands.set(m[1], new Set());
      commands.get(m[1]).add(chunk.id);
    }
  }

  const total = chunks.reduce((a, c) => a + c.length, 0) || 1;
  IDX = {
    chunks,
    byId,
    commands,
    df,
    fileByStem,
    avgLen: total / Math.max(chunks.length, 1),
    files: FILES,
  };
  return IDX;
}

/** BM25 search plus exact-command boosts, best first (port of search()). */
export function search(query, limit = 6) {
  const idx = load();
  const terms = tokenize(query);
  if (!terms.length) return [];
  const n = idx.chunks.length;
  const scores = new Map();

  for (const term of terms) {
    const df = idx.df.get(term);
    if (!df) continue;
    const idf = Math.log(1 + (n - df + 0.5) / (df + 0.5));
    for (const chunk of idx.chunks) {
      const tf = chunk.terms.get(term);
      if (!tf) continue;
      const denom = tf + K1 * (1 - B + B * (chunk.length / idx.avgLen));
      scores.set(chunk.id, (scores.get(chunk.id) || 0) + (idf * (tf * (K1 + 1))) / denom);
    }
  }

  // "/hunt", "myteam", "gymbattle" — players type command names.
  const cmds = new Set();
  for (const m of String(query).matchAll(SLASH_RE)) cmds.add(m[1]);
  for (const t of terms) {
    if (idx.commands.has(t)) cmds.add(t);
  }
  for (const cmd of cmds) {
    for (const cid of idx.commands.get(cmd) || []) {
      scores.set(cid, (scores.get(cid) || 0) + 5.0);
    }
  }

  return [...scores.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .filter(([, s]) => s > 0)
    .map(([cid, score]) => ({ chunk: byId0(cid), score }));
}

function byId0(cid) {
  return load().byId.get(cid);
}

/** Best BM25 score for a query (1 hit). */
export function bestScore(query) {
  const hits = search(query, 1);
  return hits.length ? hits[0].score : 0;
}

/** Fraction of the query's content words that exist in the docs — this
 *  (not the raw score) separates "shiny odds" from "write me a script". */
export function queryCoverage(query) {
  const idx = load();
  const terms = tokenize(query);
  if (!terms.length) return 0;
  let hits = 0;
  for (const term of terms) if (idx.df.get(term)) hits += 1;
  return hits / terms.length;
}

/** The `- /name — …` index line for a command, if documented. */
export function commandLine(name) {
  const idx = load();
  const needle = `- \`/${String(name).toLowerCase().replace(/^\//, '')}\` —`;
  for (const chunk of idx.chunks) {
    if (chunk.source.endsWith('commands.md') && chunk.text.includes(needle)) {
      for (const line of chunk.text.split('\n')) {
        if (line.startsWith(needle)) return line;
      }
    }
  }
  return null;
}

// ── guides ───────────────────────────────────────────────────────────────

/** [[stem, h1Title, characters]] for the curated guides. */
export function guides() {
  load();
  return FILES
    .filter((f) => !f.source.startsWith('generated/'))
    .map((f) => [f.stem, f.title, f.text.length])
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

/** Full markdown for a guide stem (with fuzzy fallback, port of guide_text). */
export function guideText(stem) {
  const idx = load();
  const entry = idx.fileByStem.get(stem) || idx.fileByStem.get(closest(stem, idx.fileByStem));
  return entry ? entry.text : null;
}

export function guideTitle(stem) {
  const entry = load().fileByStem.get(stem);
  return entry ? entry.title : stem;
}

/** Best guide stem for a topic word (used by the menu buttons). */
export function fileForTerm(term) {
  const idx = load();
  term = String(term || '').toLowerCase();
  if (idx.fileByStem.has(term)) return term;
  let best = null;
  let bestHits = 0;
  for (const f of FILES) {
    if (f.source.startsWith('generated/')) continue;
    const hay = `${f.stem} ${f.title}`.toLowerCase();
    let hits = 0;
    for (const t of tokenize(term)) if (hay.includes(t)) hits += 1;
    if (hits > bestHits) {
      best = f.stem;
      bestHits = hits;
    }
  }
  return best;
}

/** Build the retrieval context block sent to the model (port of context_for). */
export function contextFor(query, budget) {
  const picked = [];
  const seen = new Set();
  let used = 0;
  for (const hit of search(query, 8)) {
    const chunk = hit.chunk;
    if (seen.has(chunk.id)) continue;
    const addition = chunk.text.length + chunk.heading.length + 40;
    if (used + addition > budget && picked.length) continue;
    seen.add(chunk.id);
    picked.push(chunk);
    used += addition;
  }
  if (!picked.length) return ['', []];
  const blocks = [];
  const sources = [];
  for (const chunk of picked) {
    const head = chunk.heading ? `### ${chunk.heading}` : `### ${chunk.source}`;
    blocks.push(`${head}\n(source: ${chunk.source})\n${chunk.text}`);
    if (!sources.includes(chunk.source)) sources.push(chunk.source);
  }
  return [blocks.join('\n\n---\n\n'), sources];
}

export function stats() {
  const idx = load();
  return {
    chunks: idx.chunks.length,
    files: FILES.length,
    commands: idx.commands.size,
  };
}

// ── helpers ──────────────────────────────────────────────────────────────

function closest(stem, files) {
  stem = String(stem || '').toLowerCase();
  for (const candidate of files.keys()) {
    if (stem.includes(candidate) || candidate.includes(stem)) return candidate;
  }
  return stem;
}
